export async function keyDownOnInput(keys) {
  if (document.activeElement !== getInput()) {
    getInput().focus()
  }

  await user.keyboard(keys)
}

export async function changeInputValue(inputValue) {
  if (document.activeElement !== getInput()) {
    getInput().focus()
  }

  await user.keyboard(inputValue)
}

